package com.hau.notification.application;import com.hau.notification.application.service.NotificationService;import com.hau.notification.domain.exception.ForbiddenNotificationAccessException;import com.hau.notification.domain.model.*;import com.hau.notification.domain.repository.NotificationRepository;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;class NotificationServiceTest{@Test void cannotReadAnotherUsersNotification(){var r=mock(NotificationRepository.class);UUID owner=UUID.randomUUID(),id=UUID.randomUUID();when(r.findById(id)).thenReturn(Optional.of(new Notification(id,owner,NotificationType.SYSTEM,"T","C",null,null,false,null,Instant.EPOCH)));var s=new NotificationService(r,Clock.systemUTC());assertThatThrownBy(()->s.markRead(UUID.randomUUID(),id)).isInstanceOf(ForbiddenNotificationAccessException.class);verify(r,never()).save(any());}}
